-- partes ausentes em um quadro mantem a pose anterior (preenchido na
-- geracao); aqui todas as seis partes ja vem preenchidas em todos os
-- quadros, inclusive o Head/LA que estavam tremendo na versao defeituosa.
local PARTES = {
    T = "Torso", H = "Head", LA = "Left Arm",
    RA = "Right Arm", LL = "Left Leg", RL = "Right Leg",
}

local function novoClip()
    local sequencia = Instance.new("KeyframeSequence")
    sequencia.Name = "P17_Corpo_013"
    sequencia.Loop = true
    sequencia.Priority = Enum.AnimationPriority.Idle
    for _, quadro in ipairs(QUADROS) do
        local keyframe = Instance.new("Keyframe")
        keyframe.Time = quadro[1]
        local raiz = Instance.new("Pose")
        raiz.Name = "HumanoidRootPart"
        raiz.Weight = 0
        raiz.EasingStyle = Enum.PoseEasingStyle.Linear
        local torso = Instance.new("Pose")
        torso.Name = "Torso"
        torso.Weight = 1
        torso.EasingStyle = Enum.PoseEasingStyle.Linear
        torso.CFrame = CFrame.new(table.unpack(quadro[2].T))
        torso.Parent = raiz
        for sigla, nome in pairs(PARTES) do
            if sigla ~= "T" then
                local pose = Instance.new("Pose")
                pose.Name = nome
                pose.Weight = 1
                pose.EasingStyle = Enum.PoseEasingStyle.Linear
                pose.CFrame = CFrame.new(table.unpack(quadro[2][sigla]))
                pose.Parent = torso
            end
        end
        raiz.Parent = keyframe
        keyframe.Parent = sequencia
    end
    return sequencia
end

local substituto = novoClip()
local antigo = library:FindFirstChild("P17_Corpo_013")
if antigo then antigo:Destroy() end
substituto.Parent = library
library:SetAttribute("P17_Corpo_013_Corrigido", true)
print(("[P17 Hotfix] CrouchIdle reconstruido: %s quadros, %.3f s"):format(
    #QUADROS, QUADROS[#QUADROS][1]))
